func (this *Wallex) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var url any = Add(Add(GetValue(GetValue(this.Urls, "api"), "rest"), "/"), this.ImplodeParams(path, params))
	var query any = this.Omit(params, this.ExtractParams(path))
	headers = map[string]any{}
	if IsEqual(api, "private") {
		// wallex authenticates with the raw key in x-api-key, there is no secret and no hmac signature
		this.CheckRequiredCredentials()
		AddElementToObject(headers, "X-API-KEY", this.ApiKey)
	}
	if IsEqual(method, "GET") {
		if IsGreaterThan(GetArrayLength(ObjectKeys(query)), 0) {
			url = Add(url, Add("?", this.Urlencode(query)))
		}
	} else {
		body = this.Json(query)
		AddElementToObject(headers, "Content-Type", "application/json")
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
